<?php
namespace App\Http\Controllers;
use App\Models\MembershipCategory;use Illuminate\Http\Request;
class CategoryController extends Controller {private function admin(){abort_unless(auth()->user()->role==='admin',403);} public function index(){$this->admin();$categories=MembershipCategory::withCount('members')->orderBy('name')->get();return view('categories.index',compact('categories'));} public function store(Request $r){$this->admin();$d=$r->validate(['name'=>'required|string|max:100|unique:membership_categories,name','description'=>'nullable|string']);MembershipCategory::create($d);return back()->with('success','Category created.');} public function update(Request $r,MembershipCategory $category){$this->admin();$d=$r->validate(['name'=>'required|string|max:100|unique:membership_categories,name,'.$category->id,'description'=>'nullable|string','is_active'=>'nullable|boolean']);$category->update($d);return back()->with('success','Category updated.');} public function destroy(MembershipCategory $category){$this->admin();if($category->members()->exists())return back()->with('error','This category is assigned to members. Deactivate it instead.');$category->delete();return back()->with('success','Category deleted.');}}
